package com.android.messaging.sms;
import android.content.ContentValues;import android.content.Context;import android.database.Cursor;import android.net.Uri;import android.provider.Telephony;import com.android.messaging.util.AppPrefs;import com.android.messaging.util.ContactResolver;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;
public final class SmsRepository {
 public static final class Conversation{public long threadId,messageId,date;public String address,title,snippet;public int type,unread;}
 public static final class Message{public long id,date;public String address,body;public int type,status,error;}
 private SmsRepository(){}
 public static List<Conversation> conversations(Context c,boolean archived){LinkedHashMap<Long,Conversation>map=new LinkedHashMap<>();Cursor x=null;try{x=c.getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{Telephony.Sms._ID,Telephony.Sms.THREAD_ID,Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.DATE,Telephony.Sms.TYPE,Telephony.Sms.READ},null,null,Telephony.Sms.DATE+" DESC");int scan=0;if(x!=null)while(x.moveToNext()&&scan++<20000){long id=x.getLong(1);if(id<=0)continue;Conversation q=map.get(id);if(q==null){q=new Conversation();q.messageId=x.getLong(0);q.threadId=id;q.address=x.getString(2);q.snippet=x.getString(3);q.date=x.getLong(4);q.type=x.getInt(5);map.put(id,q);}if(x.getInt(5)==Telephony.Sms.MESSAGE_TYPE_INBOX&&x.getInt(6)==0)q.unread++;}}finally{if(x!=null)x.close();}ArrayList<Conversation>out=new ArrayList<>();for(Conversation q:map.values()){if(AppPrefs.isArchived(c,q.threadId)!=archived)continue;q.title=ContactResolver.name(c,q.address);out.add(q);}return out;}
 public static List<Message> messages(Context c,long thread){ArrayList<Message>out=new ArrayList<>();Cursor x=null;try{x=c.getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{Telephony.Sms._ID,Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.DATE,Telephony.Sms.TYPE,Telephony.Sms.STATUS,Telephony.Sms.ERROR_CODE},Telephony.Sms.THREAD_ID+"=?",new String[]{Long.toString(thread)},Telephony.Sms.DATE+" ASC");if(x!=null)while(x.moveToNext()){Message m=new Message();m.id=x.getLong(0);m.address=x.getString(1);m.body=x.getString(2);m.date=x.getLong(3);m.type=x.getInt(4);m.status=x.getInt(5);m.error=x.getInt(6);out.add(m);}}finally{if(x!=null)x.close();}return out;}
 public static void markRead(Context c,long thread){ContentValues v=new ContentValues();v.put(Telephony.Sms.READ,1);v.put(Telephony.Sms.SEEN,1);c.getContentResolver().update(Telephony.Sms.CONTENT_URI,v,Telephony.Sms.THREAD_ID+"=?",new String[]{Long.toString(thread)});}
 public static void deleteThread(Context c,long thread){c.getContentResolver().delete(Telephony.Sms.CONTENT_URI,Telephony.Sms.THREAD_ID+"=?",new String[]{Long.toString(thread)});AppPrefs.archive(c,thread,false);}
 public static void deleteMessage(Context c,long id){c.getContentResolver().delete(Uri.withAppendedPath(Telephony.Sms.CONTENT_URI,Long.toString(id)),null,null);}
}
